{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MAPLEMONK.PHILIPS_SWIGGY_SALES_FACT_ITEMS AS SELECT DISTINCT CONCAT( a.STORE_ID, \'-\', a.ITEM_CODE, a.AREA_NAME, \'-\', UPPER(a.CITY), \'-\', a.VARIANT, \'-\', CAST(a.UNITS_SOLD AS FLOAT), a.GMV, a.ORDERED_DATE ) AS ORDER_ID, TO_DATE(LEFT(a.ORDERED_DATE, 10)) AS ORDER_DATE, REPLACE(c.MRP, \',\', \'\')::FLOAT * a.UNITS_SOLD::FLOAT AS SELLING_PRICE, UPPER(a.CITY) AS CITY, UPPER(a.BRAND) AS BRAND, a.VARIANT, CAST(REPLACE(c.MRP, \',\', \'\') AS FLOAT) AS MRP, a.STORE_ID, a.AREA_NAME, a.ITEM_CODE, CAST(a.UNITS_SOLD AS FLOAT) AS QUANTITY, UPPER(b.CATEGORY) AS PRODUCT_CATEGORY, UPPER(b.SUB_CATEGORY) AS PRODUCT_SUB_CATEGORY, UPPER(CONCAT(b.PRODUCT_NAME, a.PRODUCT_NAME)) AS PRODUCT_NAME, b.PRIMARYKEY AS SKU FROM MAPLEMONK.PHILIPS_SWIGGY_SALES a LEFT JOIN ( SELECT DISTINCT \"SWIGGY ID\", PRIMARYKEY, CATEGORY, SUB_CATEGORY, \"PRODUCT TITLE\" AS PRODUCT_NAME FROM PHILIPS_DB.MAPLEMONK.PHILIPS_GS_SKU_MASTER ) b ON a.ITEM_CODE = b.\"SWIGGY ID\" LEFT JOIN ( SELECT * FROM PHILIPS_DB.MAPLEMONK.PHILIPS_GS_SKU_MRP_COGS WHERE LOWER(MARKETPLACE) = \'swiggy\' ) c ON UPPER(TRIM(b.PRIMARYKEY)) = UPPER(TRIM(c.SKU_CODE)) AND TO_DATE(LEFT(a.ORDERED_DATE, 10)) BETWEEN c.START_DATE AND c.END_DATE WHERE TO_DATE(LEFT(a.ORDERED_DATE, 10)) > ( SELECT MAX(DATE) FROM PHILIPS_DB.MAPLEMONK.QUICK_COMMERCE_HISTORICAL_SALES WHERE LOWER(PLATFORM) = \'swiggy\' ) AND LOWER(COALESCE(a.PRODUCT_NAME, b.PRODUCT_NAME)) NOT LIKE \'%mixer grinder%\' AND LOWER(COALESCE(a.PRODUCT_NAME, b.PRODUCT_NAME)) NOT LIKE \'%blender%\' AND LOWER(COALESCE(a.PRODUCT_NAME, b.PRODUCT_NAME)) NOT LIKE \'%speaker%\' AND LOWER(COALESCE(a.PRODUCT_NAME, b.PRODUCT_NAME)) NOT LIKE \'%maaza%\' AND LOWER(COALESCE(a.PRODUCT_NAME, b.PRODUCT_NAME)) NOT LIKE \'%lighting%\' UNION ALL SELECT NULL AS ORDER_ID, DATE AS ORDER_DATE, VALUE::FLOAT AS SELLING_PRICE, UPPER(CITY) AS CITY, NULL AS BRAND, NULL AS VARIANT, MCSI AS MRP, NULL AS STORE_ID, NULL AS AREA_NAME, SKU_ITEM_ID AS ITEM_CODE, QTY::FLOAT AS QUANTITY, UPPER(BU) AS PRODUCT_CATEGORY, UPPER(SAG) AS PRODUCT_SUB_CATEGORY, UPPER(ITEM_DESCRIPTION) AS PRODUCT_NAME, CTN AS SKU FROM PHILIPS_DB.MAPLEMONK.QUICK_COMMERCE_HISTORICAL_SALES a WHERE LOWER(PLATFORM) = \'swiggy\' AND LOWER(a.ITEM_DESCRIPTION) NOT LIKE \'%mixer grinder%\' AND LOWER(a.ITEM_DESCRIPTION) NOT LIKE \'%blender%\' AND LOWER(a.ITEM_DESCRIPTION) NOT LIKE \'%speaker%\' AND LOWER(a.ITEM_DESCRIPTION) NOT LIKE \'%maaza%\' AND LOWER(a.ITEM_DESCRIPTION) NOT LIKE \'%lighting%\';",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from PHILIPS_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            